const FILES = {
  "/": {
    "body": "<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#122620\">\n  <meta name=\"description\" content=\"Androidで営業テレアポを素早く回すための架電サポートツール\">\n  <link rel=\"manifest\" href=\"./manifest.webmanifest\">\n  <title>テレアポ架電サポート</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --ink: #0f2147;\n      --muted: #71809f;\n      --line: #e3e9f4;\n      --paper: #f7faff;\n      --panel: #ffffff;\n      --deep: #073b8f;\n      --mint: #d9eaff;\n      --leaf: #0b58c9;\n      --blue: #0b58c9;\n      --amber: #ea6b1a;\n      --green: #168653;\n      --red: #e33447;\n      --shadow: 0 12px 28px rgba(13, 45, 94, .08);\n      font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      background: #ffffff;\n      color: var(--ink);\n      min-height: 100svh;\n    }\n\n    button, input, textarea, select {\n      font: inherit;\n    }\n\n    button {\n      border: 0;\n      cursor: pointer;\n      -webkit-tap-highlight-color: transparent;\n    }\n\n    .app {\n      width: min(100%, 430px);\n      margin: 0 auto;\n      padding: 10px 14px 18px;\n      padding-bottom: calc(24px + env(safe-area-inset-bottom));\n    }\n\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 12px;\n      min-height: 50px;\n      margin: 0 0 8px;\n      position: relative;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      min-width: 0;\n    }\n\n    .mark {\n      width: 24px;\n      height: 24px;\n      border-radius: 0;\n      background: transparent;\n      display: grid;\n      place-items: center;\n      color: var(--deep);\n      flex: 0 0 auto;\n    }\n\n    .brand h1 {\n      font-size: 14px;\n      color: var(--deep);\n      line-height: 1.1;\n      margin: 0;\n    }\n\n    .brand p {\n      display: none;\n    }\n\n    .pill {\n      position: absolute;\n      right: 0;\n      top: 13px;\n      background: transparent;\n      color: var(--deep);\n      border: 0;\n      padding: 0;\n      font-size: 12px;\n    }\n\n    .grid {\n      display: block;\n    }\n\n    .panel {\n      background: #ffffff;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      box-shadow: none;\n    }\n\n    .hero {\n      padding: 0;\n      display: grid;\n      gap: 8px;\n      border: 0;\n      box-shadow: none;\n    }\n\n    .meta {\n      display: flex;\n      justify-content: space-between;\n      gap: 12px;\n      display: none;\n      font-size: 13px;\n    }\n\n    .target h2 {\n      margin: 0;\n      font-size: 20px;\n      line-height: 1.2;\n      letter-spacing: 0;\n    }\n\n    .target .company {\n      color: var(--blue);\n      font-size: 15px;\n      min-height: 21px;\n    }\n\n    .phone {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding: 14px;\n      background: #fff;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n    }\n\n    .phone::before {\n      content: \"電話番号\";\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 700;\n      white-space: nowrap;\n    }\n\n    .phone strong {\n      font-size: 16px;\n      color: var(--blue);\n      letter-spacing: 0;\n      overflow-wrap: anywhere;\n      flex: 1;\n    }\n\n    .icon-button {\n      width: 46px;\n      height: 46px;\n      border-radius: 8px;\n      background: #ffffff;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      display: grid;\n      place-items: center;\n      flex: 0 0 auto;\n    }\n\n    .call-row {\n      display: grid;\n      grid-template-columns: 1fr 56px;\n      gap: 10px;\n    }\n\n    .call {\n      min-height: 58px;\n      border-radius: 8px;\n      background: var(--deep);\n      color: white;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 10px;\n      text-decoration: none;\n      font-weight: 800;\n      font-size: 19px;\n    }\n\n    .call[aria-disabled=\"true\"] {\n      background: #a7b0ab;\n      pointer-events: none;\n    }\n\n    .next {\n      min-height: 58px;\n      border-radius: 8px;\n      background: #eef5ff;\n      color: var(--deep);\n      color: white;\n      display: grid;\n      place-items: center;\n    }\n\n    .status-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 8px;\n    }\n\n    .status {\n      min-height: 74px;\n      border-radius: 8px;\n      background: #f7f9fc;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      font-weight: 700;\n    }\n\n    .status[data-kind=\"hot\"] { background: #eef6ff; color: var(--blue); border-color: #d5e7ff; }\n    .status[data-kind=\"later\"] { background: #fff6ed; color: var(--amber); border-color: #ffe3c7; }\n    .status[data-kind=\"bad\"] { background: #fff1f2; color: var(--red); border-color: #ffd4d9; }\n\n    .notes {\n      display: grid;\n      gap: 8px;\n    }\n\n    textarea, input {\n      width: 100%;\n      border-radius: 8px;\n      border: 1px solid var(--line);\n      background: #fff;\n      color: var(--ink);\n      padding: 12px;\n      outline: none;\n    }\n\n    textarea {\n      min-height: 88px;\n      resize: vertical;\n    }\n\n    .section {\n      padding: 0;\n      display: grid;\n      gap: 12px;\n      border: 0;\n      box-shadow: none;\n    }\n\n    .section-title {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n    }\n\n    .section-title h3 {\n      margin: 0;\n      font-size: 16px;\n    }\n\n    .section-title span {\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .tabs {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 6px;\n      background: #f3f6fb;\n      padding: 5px;\n      border-radius: 8px;\n    }\n\n    .tab {\n      min-height: 38px;\n      border-radius: 7px;\n      color: #6f7fa1;\n      background: transparent;\n      font-weight: 700;\n    }\n\n    .tab.active {\n      background: #fff;\n      color: var(--deep);\n      box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n    }\n\n    .tab-panel {\n      display: none;\n      gap: 10px;\n    }\n\n    .tab-panel.active {\n      display: grid;\n    }\n\n    .actions {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 8px;\n    }\n\n    .file-picker {\n      display: grid;\n      gap: 8px;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fbfcfa;\n    }\n\n    .file-picker input {\n      padding: 10px;\n      background: #fff;\n    }\n\n    .secondary {\n      min-height: 46px;\n      border-radius: 8px;\n      background: #fff;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      font-weight: 700;\n    }\n\n    .primary {\n      min-height: 46px;\n      border-radius: 8px;\n      background: var(--deep);\n      color: #fff;\n      font-weight: 800;\n    }\n\n    .danger {\n      color: var(--red);\n    }\n\n    .list {\n      display: grid;\n      gap: 8px;\n      max-height: none;\n      overflow: auto;\n      padding-right: 2px;\n    }\n\n    .row {\n      border: 0;\n      border-bottom: 1px solid var(--line);\n      background: #fff;\n      border-radius: 0;\n      padding: 12px 4px;\n      display: grid;\n      grid-template-columns: 1fr 76px;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .row.current {\n      background: #f7faff;\n    }\n\n    .row button {\n      background: transparent;\n      text-align: left;\n      padding: 0;\n      color: inherit;\n      min-width: 0;\n    }\n\n    .row-call {\n      min-height: 38px;\n      border-radius: 8px;\n      background: #eef5ff;\n      color: var(--blue);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 4px;\n      font-size: 13px;\n      font-weight: 800;\n      text-decoration: none;\n    }\n\n    .row-call svg {\n      width: 16px;\n      height: 16px;\n    }\n\n    .row-call[aria-disabled=\"true\"] {\n      color: #aeb8cc;\n      pointer-events: none;\n    }\n\n    .row-main {\n      display: flex;\n      justify-content: space-between;\n      gap: 8px;\n      font-size: 14px;\n      font-weight: 800;\n    }\n\n    .row-sub {\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .empty {\n      border: 1px dashed #b8c1bc;\n      border-radius: 8px;\n      padding: 16px;\n      color: var(--muted);\n      text-align: center;\n      background: #fbfcfa;\n    }\n\n    .export-box {\n      min-height: 180px;\n      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n      font-size: 12px;\n      line-height: 1.45;\n      white-space: pre;\n      overflow: auto;\n    }\n\n    .hint {\n      color: var(--muted);\n      font-size: 12px;\n      line-height: 1.5;\n    }\n\n    .toast {\n      position: fixed;\n      left: 14px;\n      right: 14px;\n      bottom: calc(14px + env(safe-area-inset-bottom));\n      min-height: 46px;\n      border-radius: 8px;\n      background: rgba(7, 38, 91, .96);\n      color: white;\n      display: none;\n      place-items: center;\n      padding: 12px;\n      z-index: 20;\n      text-align: center;\n      box-shadow: var(--shadow);\n    }\n\n    .toast.show {\n      display: grid;\n    }\n\n    svg {\n      width: 22px;\n      height: 22px;\n      stroke: currentColor;\n      stroke-width: 2.2;\n      stroke-linecap: round;\n      stroke-linejoin: round;\n      fill: none;\n    }\n\n    .back {\n      position: absolute;\n      left: 0;\n      top: 7px;\n      width: 36px;\n      height: 36px;\n      border-radius: 8px;\n      background: transparent;\n      color: var(--deep);\n      display: none;\n      place-items: center;\n    }\n\n    .app.action-mode .back { display: grid; }\n    .app.action-mode .section { display: none; }\n    .app:not(.action-mode) .hero { display: none; }\n\n    .search {\n      position: relative;\n    }\n\n    .search input {\n      padding-left: 38px;\n      height: 42px;\n    }\n\n    .search svg {\n      position: absolute;\n      left: 12px;\n      top: 10px;\n      color: #7a88a6;\n      width: 19px;\n      height: 19px;\n    }\n\n    .target-card {\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 16px;\n      display: grid;\n      gap: 4px;\n      margin-bottom: 8px;\n    }\n  </style>\n</head>\n<body>\n  <main class=\"app\" id=\"app\">\n    <header>\n      <button class=\"back\" id=\"backToList\" aria-label=\"リストへ戻る\" title=\"リストへ戻る\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"m15 18-6-6 6-6\"/></svg>\n      </button>\n      <div class=\"brand\">\n        <div class=\"mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg>\n        </div>\n        <div>\n          <h1>テレアポ架電サポート</h1>\n          <p>番号準備、発信、結果記録を1画面で</p>\n        </div>\n      </div>\n      <div class=\"pill\" id=\"progressPill\">0 / 0</div>\n    </header>\n\n    <div class=\"grid\">\n      <section class=\"panel hero\" aria-label=\"現在の架電先\">\n        <div class=\"meta\">\n          <span id=\"queueLabel\">架電リストなし</span>\n          <span id=\"lastStatus\">未記録</span>\n        </div>\n\n        <div class=\"target-card\">\n          <div class=\"target\">\n            <h2 id=\"targetName\">CSVを追加してください</h2>\n            <div class=\"company\" id=\"targetCompany\">会社名、担当者名、電話番号を読み込めます</div>\n          </div>\n\n          <div class=\"phone\">\n            <strong id=\"targetPhone\">---</strong>\n            <button class=\"icon-button\" id=\"copyPhone\" aria-label=\"電話番号をコピー\" title=\"電話番号をコピー\">\n              <svg viewBox=\"0 0 24 24\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            </button>\n          </div>\n        </div>\n\n        <div class=\"call-row\">\n          <a class=\"call\" id=\"callLink\" href=\"#\" aria-disabled=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg>\n            この番号に発信\n          </a>\n          <button class=\"next\" id=\"nextButton\" aria-label=\"次へ\" title=\"次へ\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14\"/><path d=\"m12 5 7 7-7 7\"/></svg>\n          </button>\n        </div>\n\n        <div class=\"status-grid\" aria-label=\"通話結果\">\n          <button class=\"status\" data-result=\"不在\">不在</button>\n          <button class=\"status\" data-result=\"担当者不在\">担当者不在</button>\n          <button class=\"status\" data-result=\"再架電\" data-kind=\"later\">再架電</button>\n          <button class=\"status\" data-result=\"見込みあり\" data-kind=\"hot\">見込みあり</button>\n          <button class=\"status\" data-result=\"資料送付\" data-kind=\"hot\">資料送付</button>\n          <button class=\"status\" data-result=\"受付NG\" data-kind=\"bad\">受付NG</button>\n          <button class=\"status\" data-result=\"番号違い\" data-kind=\"bad\">番号違い</button>\n          <button class=\"status\" data-result=\"完了\">完了</button>\n        </div>\n\n        <div class=\"notes\">\n          <input id=\"callbackAt\" type=\"datetime-local\" aria-label=\"再架電日時\">\n          <textarea id=\"memo\" placeholder=\"会話メモ、受付名、次回アクションなど\"></textarea>\n          <button class=\"primary\" id=\"saveMemo\">メモだけ保存</button>\n        </div>\n      </section>\n\n      <section class=\"panel section\" aria-label=\"リスト管理\">\n        <div class=\"tabs\" role=\"tablist\">\n          <button class=\"tab active\" data-tab=\"list\" role=\"tab\">リスト</button>\n          <button class=\"tab\" data-tab=\"import\" role=\"tab\">追加</button>\n          <button class=\"tab\" data-tab=\"export\" role=\"tab\">出力</button>\n        </div>\n\n        <div class=\"tab-panel active\" id=\"tab-list\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>架電先</h3>\n            <span id=\"countLabel\">0件</span>\n          </div>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"openExport\">リストを出力</button>\n            <button class=\"secondary\" id=\"copyListCsv\">リストをコピー</button>\n          </div>\n          <div class=\"search\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.35-4.35\"/></svg>\n            <input id=\"searchInput\" placeholder=\"会社名・担当者名で検索\" autocomplete=\"off\">\n          </div>\n          <div class=\"list\" id=\"contactList\"></div>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-import\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>CSVファイル取り込み</h3>\n            <span>スマホから選択</span>\n          </div>\n          <div class=\"file-picker\">\n            <input id=\"csvFile\" type=\"file\" accept=\".csv,text/csv\" aria-label=\"CSVファイルを選択\">\n            <p class=\"hint\">Androidのファイル、Google Drive、ダウンロード内のCSVを選べます。</p>\n          </div>\n\n          <div class=\"section-title\">\n            <h3>CSV貼り付け</h3>\n            <span>名前,会社,電話</span>\n          </div>\n          <textarea id=\"csvInput\" placeholder=\"例&#10;山田太郎,山田工務店,090-1234-5678&#10;佐藤花子,佐藤商事,03-1234-5678\"></textarea>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"importCsv\">CSVを取り込む</button>\n            <button class=\"secondary\" id=\"loadSample\">サンプル</button>\n          </div>\n\n          <div class=\"section-title\">\n            <h3>1件追加</h3>\n            <span>手入力</span>\n          </div>\n          <input id=\"manualName\" placeholder=\"担当者名\">\n          <input id=\"manualCompany\" placeholder=\"会社名\">\n          <input id=\"manualPhone\" inputmode=\"tel\" placeholder=\"電話番号\">\n          <button class=\"primary\" id=\"addManual\">追加する</button>\n          <p class=\"hint\">CSVの1行目が見出しでも取り込めます。電話番号らしい列を自動で探します。</p>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-export\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>記録の出力</h3>\n            <span>CSV</span>\n          </div>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"exportCsv\">CSVをダウンロード</button>\n            <button class=\"secondary\" id=\"copyCsv\">CSVをコピー</button>\n          </div>\n          <div class=\"actions\">\n            <button class=\"secondary\" id=\"shareCsv\">共有する</button>\n            <button class=\"secondary\" id=\"refreshExport\">表示を更新</button>\n          </div>\n          <textarea class=\"export-box\" id=\"exportText\" readonly aria-label=\"出力CSV\"></textarea>\n          <button class=\"secondary danger\" id=\"clearData\">全データを削除</button>\n          <p class=\"hint\">データはこの端末のブラウザ内に保存されます。サーバーには送信しません。</p>\n        </div>\n      </section>\n    </div>\n  </main>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script>\n    const STORAGE_KEY = \"teleapo-assist-v1\";\n    const $ = (selector) => document.querySelector(selector);\n    const $$ = (selector) => Array.from(document.querySelectorAll(selector));\n\n    const state = loadState();\n\n    function loadState() {\n      try {\n        const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || \"{}\");\n        return {\n          contacts: Array.isArray(saved.contacts) ? saved.contacts : [],\n          current: Number.isInteger(saved.current) ? saved.current : 0\n        };\n      } catch {\n        return { contacts: [], current: 0 };\n      }\n    }\n\n    function persist() {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n    }\n\n    function normalizePhone(value) {\n      return String(value || \"\").replace(/[^\\d+]/g, \"\");\n    }\n\n    function displayPhone(value) {\n      return String(value || \"\").trim() || \"---\";\n    }\n\n    function currentContact() {\n      if (!state.contacts.length) return null;\n      if (state.current < 0) state.current = 0;\n      if (state.current >= state.contacts.length) state.current = state.contacts.length - 1;\n      return state.contacts[state.current];\n    }\n\n    function render() {\n      const contact = currentContact();\n      const total = state.contacts.length;\n      $(\"#progressPill\").textContent = total ? `${state.current + 1} / ${total}` : \"0 / 0\";\n      $(\"#countLabel\").textContent = `${total}件`;\n      $(\"#queueLabel\").textContent = total ? `次の架電先` : \"架電リストなし\";\n      updateExportPreview();\n\n      if (!contact) {\n        $(\"#targetName\").textContent = \"CSVを追加してください\";\n        $(\"#targetCompany\").textContent = \"会社名、担当者名、電話番号を読み込めます\";\n        $(\"#targetPhone\").textContent = \"---\";\n        $(\"#lastStatus\").textContent = \"未記録\";\n        $(\"#memo\").value = \"\";\n        $(\"#callbackAt\").value = \"\";\n        $(\"#callLink\").href = \"#\";\n        $(\"#callLink\").setAttribute(\"aria-disabled\", \"true\");\n        renderList();\n        return;\n      }\n\n      $(\"#targetName\").textContent = contact.company || contact.name || \"名前なし\";\n      $(\"#targetCompany\").textContent = contact.name || \"担当者なし\";\n      $(\"#targetPhone\").textContent = displayPhone(contact.phone);\n      $(\"#lastStatus\").textContent = contact.result || \"未記録\";\n      $(\"#memo\").value = contact.memo || \"\";\n      $(\"#callbackAt\").value = contact.callbackAt || \"\";\n\n      const normalized = normalizePhone(contact.phone);\n      $(\"#callLink\").href = normalized ? `tel:${normalized}` : \"#\";\n      $(\"#callLink\").setAttribute(\"aria-disabled\", normalized ? \"false\" : \"true\");\n      renderList();\n      persist();\n    }\n\n    function renderList() {\n      const list = $(\"#contactList\");\n      list.innerHTML = \"\";\n      if (!state.contacts.length) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"empty\";\n        empty.textContent = \"追加タブから架電先を入れてください\";\n        list.appendChild(empty);\n        return;\n      }\n\n      const query = ($(\"#searchInput\")?.value || \"\").trim().toLowerCase();\n      const visibleContacts = state.contacts\n        .map((contact, index) => ({ contact, index }))\n        .filter(({ contact }) => {\n          if (!query) return true;\n          return [contact.name, contact.company, contact.phone, contact.result]\n            .join(\" \")\n            .toLowerCase()\n            .includes(query);\n        });\n\n      if (!visibleContacts.length) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"empty\";\n        empty.textContent = \"一致する架電先がありません\";\n        list.appendChild(empty);\n        return;\n      }\n\n      visibleContacts.forEach(({ contact, index }) => {\n        const row = document.createElement(\"div\");\n        row.className = `row${index === state.current ? \" current\" : \"\"}`;\n        const button = document.createElement(\"button\");\n        button.type = \"button\";\n        button.addEventListener(\"click\", () => {\n          state.current = index;\n          render();\n          switchTab(\"action\");\n        });\n        button.innerHTML = `\n          <div class=\"row-main\">\n            <span>${escapeHtml(contact.company || contact.name || \"名前なし\")}</span>\n            <span>${escapeHtml(contact.result || \"\")}</span>\n          </div>\n          <div class=\"row-sub\">${escapeHtml(contact.name || \"担当者なし\")}　${escapeHtml(displayPhone(contact.phone))}</div>\n        `;\n        const call = document.createElement(\"a\");\n        const phone = normalizePhone(contact.phone);\n        call.className = \"row-call\";\n        call.href = phone ? `tel:${phone}` : \"#\";\n        call.setAttribute(\"aria-label\", `${contact.company || contact.name || \"架電先\"}に電話する`);\n        call.setAttribute(\"aria-disabled\", phone ? \"false\" : \"true\");\n        call.innerHTML = `<svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg><span>発信</span>`;\n        row.appendChild(button);\n        row.appendChild(call);\n        list.appendChild(row);\n      });\n    }\n\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, (char) => ({\n        \"&\": \"&amp;\",\n        \"<\": \"&lt;\",\n        \">\": \"&gt;\",\n        \"\\\"\": \"&quot;\",\n        \"'\": \"&#039;\"\n      }[char]));\n    }\n\n    function parseCsv(text) {\n      const rows = [];\n      let field = \"\";\n      let row = [];\n      let quoted = false;\n\n      for (let i = 0; i < text.length; i += 1) {\n        const char = text[i];\n        const next = text[i + 1];\n        if (char === \"\\\"\" && quoted && next === \"\\\"\") {\n          field += \"\\\"\";\n          i += 1;\n        } else if (char === \"\\\"\") {\n          quoted = !quoted;\n        } else if (char === \",\" && !quoted) {\n          row.push(field.trim());\n          field = \"\";\n        } else if ((char === \"\\n\" || char === \"\\r\") && !quoted) {\n          if (char === \"\\r\" && next === \"\\n\") i += 1;\n          row.push(field.trim());\n          if (row.some(Boolean)) rows.push(row);\n          row = [];\n          field = \"\";\n        } else {\n          field += char;\n        }\n      }\n      row.push(field.trim());\n      if (row.some(Boolean)) rows.push(row);\n      return rows;\n    }\n\n    function rowsToContacts(rows) {\n      if (!rows.length) return [];\n      const header = rows[0].map((cell) => cell.toLowerCase());\n      const hasHeader = header.some((cell) => /name|名前|担当|会社|company|phone|tel|電話/.test(cell));\n      const body = hasHeader ? rows.slice(1) : rows;\n\n      const phoneIndex = hasHeader ? header.findIndex((cell) => /phone|tel|電話|番号/.test(cell)) : -1;\n      const nameIndex = hasHeader ? header.findIndex((cell) => /name|名前|担当/.test(cell)) : -1;\n      const companyIndex = hasHeader ? header.findIndex((cell) => /company|会社|法人|店舗/.test(cell)) : -1;\n\n      return body.map((cells) => {\n        const guessedPhone = phoneIndex >= 0 ? cells[phoneIndex] : cells.find((cell) => /0\\d{1,4}[-\\d\\s()]{6,}/.test(cell)) || cells[2] || \"\";\n        const guessedName = nameIndex >= 0 ? cells[nameIndex] : cells[0] || \"\";\n        const guessedCompany = companyIndex >= 0 ? cells[companyIndex] : cells[1] || \"\";\n        return {\n          id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),\n          name: guessedName,\n          company: guessedCompany,\n          phone: guessedPhone,\n          result: \"\",\n          memo: \"\",\n          callbackAt: \"\",\n          updatedAt: \"\"\n        };\n      }).filter((contact) => contact.phone || contact.name || contact.company);\n    }\n\n    function markResult(result) {\n      const contact = currentContact();\n      if (!contact) return toast(\"先に架電先を追加してください\");\n      contact.result = result;\n      contact.memo = $(\"#memo\").value.trim();\n      contact.callbackAt = $(\"#callbackAt\").value;\n      contact.updatedAt = new Date().toISOString();\n      persist();\n      toast(`${result}で記録しました`);\n      if (state.current < state.contacts.length - 1) {\n        state.current += 1;\n      }\n      render();\n    }\n\n    function toCsv() {\n      const header = [\"名前\", \"会社\", \"電話番号\", \"結果\", \"再架電日時\", \"メモ\", \"更新日時\"];\n      const lines = state.contacts.map((contact) => [\n        contact.name,\n        contact.company,\n        contact.phone,\n        contact.result,\n        contact.callbackAt,\n        contact.memo,\n        contact.updatedAt\n      ].map(csvCell).join(\",\"));\n      return [header.join(\",\"), ...lines].join(\"\\n\");\n    }\n\n    function updateExportPreview() {\n      const box = $(\"#exportText\");\n      if (!box) return;\n      box.value = state.contacts.length ? toCsv() : \"出力できるリストがありません\";\n    }\n\n    function csvCell(value) {\n      const text = String(value || \"\");\n      return /[\",\\n\\r]/.test(text) ? `\"${text.replace(/\"/g, \"\\\"\\\"\")}\"` : text;\n    }\n\n    function toast(message) {\n      const element = $(\"#toast\");\n      element.textContent = message;\n      element.classList.add(\"show\");\n      window.clearTimeout(toast.timer);\n      toast.timer = window.setTimeout(() => element.classList.remove(\"show\"), 1800);\n    }\n\n    function switchTab(name) {\n      $(\"#app\").classList.toggle(\"action-mode\", name === \"action\");\n      if (name === \"action\") return;\n      $$(\".tab\").forEach((item) => item.classList.toggle(\"active\", item.dataset.tab === name));\n      $$(\".tab-panel\").forEach((item) => item.classList.toggle(\"active\", item.id === `tab-${name}`));\n      if (name === \"export\") updateExportPreview();\n    }\n\n    $$(\".tab\").forEach((tab) => {\n      tab.addEventListener(\"click\", () => switchTab(tab.dataset.tab));\n    });\n\n    $$(\".status\").forEach((button) => {\n      button.addEventListener(\"click\", () => markResult(button.dataset.result));\n    });\n\n    $(\"#nextButton\").addEventListener(\"click\", () => {\n      if (!state.contacts.length) return toast(\"架電先がありません\");\n      state.current = Math.min(state.current + 1, state.contacts.length - 1);\n      render();\n    });\n\n    $(\"#backToList\").addEventListener(\"click\", () => {\n      switchTab(\"list\");\n    });\n\n    $(\"#searchInput\").addEventListener(\"input\", () => {\n      renderList();\n    });\n\n    $(\"#copyPhone\").addEventListener(\"click\", async () => {\n      const contact = currentContact();\n      if (!contact || !contact.phone) return toast(\"コピーする番号がありません\");\n      try {\n        await navigator.clipboard.writeText(contact.phone);\n        toast(\"電話番号をコピーしました\");\n      } catch {\n        toast(\"コピーできませんでした\");\n      }\n    });\n\n    $(\"#openExport\").addEventListener(\"click\", () => {\n      switchTab(\"export\");\n      toast(\"出力タブを開きました\");\n    });\n\n    $(\"#copyListCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"コピーするリストがありません\");\n      try {\n        await navigator.clipboard.writeText(toCsv());\n        toast(\"リストをコピーしました\");\n      } catch {\n        switchTab(\"export\");\n        $(\"#exportText\").select();\n        toast(\"出力欄を選択しました\");\n      }\n    });\n\n    $(\"#saveMemo\").addEventListener(\"click\", () => {\n      const contact = currentContact();\n      if (!contact) return toast(\"先に架電先を追加してください\");\n      contact.memo = $(\"#memo\").value.trim();\n      contact.callbackAt = $(\"#callbackAt\").value;\n      contact.updatedAt = new Date().toISOString();\n      persist();\n      render();\n      toast(\"メモを保存しました\");\n    });\n\n    $(\"#importCsv\").addEventListener(\"click\", () => {\n      const contacts = rowsToContacts(parseCsv($(\"#csvInput\").value));\n      if (!contacts.length) return toast(\"取り込める行がありません\");\n      state.contacts.push(...contacts);\n      if (state.contacts.length === contacts.length) state.current = 0;\n      $(\"#csvInput\").value = \"\";\n      persist();\n      render();\n      toast(`${contacts.length}件取り込みました`);\n    });\n\n    $(\"#csvFile\").addEventListener(\"change\", async (event) => {\n      const file = event.target.files && event.target.files[0];\n      if (!file) return;\n\n      try {\n        const text = await file.text();\n        const contacts = rowsToContacts(parseCsv(text));\n        if (!contacts.length) {\n          event.target.value = \"\";\n          return toast(\"取り込める行がありません\");\n        }\n        state.contacts.push(...contacts);\n        if (state.contacts.length === contacts.length) state.current = 0;\n        persist();\n        render();\n        toast(`${contacts.length}件取り込みました`);\n      } catch {\n        toast(\"CSVを読み込めませんでした\");\n      } finally {\n        event.target.value = \"\";\n      }\n    });\n\n    $(\"#loadSample\").addEventListener(\"click\", () => {\n      $(\"#csvInput\").value = \"名前,会社,電話番号\\n山田太郎,山田工務店,090-1234-5678\\n佐藤花子,佐藤商事,03-1234-5678\";\n    });\n\n    $(\"#addManual\").addEventListener(\"click\", () => {\n      const contact = {\n        id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),\n        name: $(\"#manualName\").value.trim(),\n        company: $(\"#manualCompany\").value.trim(),\n        phone: $(\"#manualPhone\").value.trim(),\n        result: \"\",\n        memo: \"\",\n        callbackAt: \"\",\n        updatedAt: \"\"\n      };\n      if (!contact.name && !contact.company && !contact.phone) return toast(\"追加内容を入力してください\");\n      state.contacts.push(contact);\n      state.current = state.contacts.length - 1;\n      $(\"#manualName\").value = \"\";\n      $(\"#manualCompany\").value = \"\";\n      $(\"#manualPhone\").value = \"\";\n      persist();\n      render();\n      toast(\"1件追加しました\");\n    });\n\n    $(\"#exportCsv\").addEventListener(\"click\", () => {\n      if (!state.contacts.length) return toast(\"出力するリストがありません\");\n      const blob = new Blob([toCsv()], { type: \"text/csv;charset=utf-8\" });\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement(\"a\");\n      link.href = url;\n      link.download = `teleapo-${new Date().toISOString().slice(0, 10)}.csv`;\n      link.click();\n      URL.revokeObjectURL(url);\n    });\n\n    $(\"#copyCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"コピーするリストがありません\");\n      try {\n        await navigator.clipboard.writeText(toCsv());\n        toast(\"CSVをコピーしました\");\n      } catch {\n        $(\"#exportText\").select();\n        toast(\"出力欄を選択しました\");\n      }\n    });\n\n    $(\"#shareCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"共有するリストがありません\");\n      if (!navigator.share) {\n        $(\"#exportText\").select();\n        return toast(\"共有非対応なので出力欄を選択しました\");\n      }\n      try {\n        await navigator.share({\n          title: \"テレアポ架電リスト\",\n          text: toCsv()\n        });\n      } catch {\n        toast(\"共有をキャンセルしました\");\n      }\n    });\n\n    $(\"#refreshExport\").addEventListener(\"click\", () => {\n      updateExportPreview();\n      toast(\"出力表示を更新しました\");\n    });\n\n    $(\"#clearData\").addEventListener(\"click\", () => {\n      if (!confirm(\"すべての架電先と記録を削除しますか？\")) return;\n      state.contacts = [];\n      state.current = 0;\n      persist();\n      render();\n      toast(\"削除しました\");\n    });\n\n    if (\"serviceWorker\" in navigator && location.protocol !== \"file:\") {\n      navigator.serviceWorker.register(\"./sw.js\").catch(() => {});\n    }\n\n    render();\n  </script>\n</body>\n</html>\n",
    "type": "text/html; charset=utf-8"
  },
  "/index.html": {
    "body": "<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#122620\">\n  <meta name=\"description\" content=\"Androidで営業テレアポを素早く回すための架電サポートツール\">\n  <link rel=\"manifest\" href=\"./manifest.webmanifest\">\n  <title>テレアポ架電サポート</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --ink: #0f2147;\n      --muted: #71809f;\n      --line: #e3e9f4;\n      --paper: #f7faff;\n      --panel: #ffffff;\n      --deep: #073b8f;\n      --mint: #d9eaff;\n      --leaf: #0b58c9;\n      --blue: #0b58c9;\n      --amber: #ea6b1a;\n      --green: #168653;\n      --red: #e33447;\n      --shadow: 0 12px 28px rgba(13, 45, 94, .08);\n      font-family: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      background: #ffffff;\n      color: var(--ink);\n      min-height: 100svh;\n    }\n\n    button, input, textarea, select {\n      font: inherit;\n    }\n\n    button {\n      border: 0;\n      cursor: pointer;\n      -webkit-tap-highlight-color: transparent;\n    }\n\n    .app {\n      width: min(100%, 430px);\n      margin: 0 auto;\n      padding: 10px 14px 18px;\n      padding-bottom: calc(24px + env(safe-area-inset-bottom));\n    }\n\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 12px;\n      min-height: 50px;\n      margin: 0 0 8px;\n      position: relative;\n    }\n\n    .brand {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      min-width: 0;\n    }\n\n    .mark {\n      width: 24px;\n      height: 24px;\n      border-radius: 0;\n      background: transparent;\n      display: grid;\n      place-items: center;\n      color: var(--deep);\n      flex: 0 0 auto;\n    }\n\n    .brand h1 {\n      font-size: 14px;\n      color: var(--deep);\n      line-height: 1.1;\n      margin: 0;\n    }\n\n    .brand p {\n      display: none;\n    }\n\n    .pill {\n      position: absolute;\n      right: 0;\n      top: 13px;\n      background: transparent;\n      color: var(--deep);\n      border: 0;\n      padding: 0;\n      font-size: 12px;\n    }\n\n    .grid {\n      display: block;\n    }\n\n    .panel {\n      background: #ffffff;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      box-shadow: none;\n    }\n\n    .hero {\n      padding: 0;\n      display: grid;\n      gap: 8px;\n      border: 0;\n      box-shadow: none;\n    }\n\n    .meta {\n      display: flex;\n      justify-content: space-between;\n      gap: 12px;\n      display: none;\n      font-size: 13px;\n    }\n\n    .target h2 {\n      margin: 0;\n      font-size: 20px;\n      line-height: 1.2;\n      letter-spacing: 0;\n    }\n\n    .target .company {\n      color: var(--blue);\n      font-size: 15px;\n      min-height: 21px;\n    }\n\n    .phone {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      padding: 14px;\n      background: #fff;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n    }\n\n    .phone::before {\n      content: \"電話番号\";\n      color: var(--muted);\n      font-size: 12px;\n      font-weight: 700;\n      white-space: nowrap;\n    }\n\n    .phone strong {\n      font-size: 16px;\n      color: var(--blue);\n      letter-spacing: 0;\n      overflow-wrap: anywhere;\n      flex: 1;\n    }\n\n    .icon-button {\n      width: 46px;\n      height: 46px;\n      border-radius: 8px;\n      background: #ffffff;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      display: grid;\n      place-items: center;\n      flex: 0 0 auto;\n    }\n\n    .call-row {\n      display: grid;\n      grid-template-columns: 1fr 56px;\n      gap: 10px;\n    }\n\n    .call {\n      min-height: 58px;\n      border-radius: 8px;\n      background: var(--deep);\n      color: white;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 10px;\n      text-decoration: none;\n      font-weight: 800;\n      font-size: 19px;\n    }\n\n    .call[aria-disabled=\"true\"] {\n      background: #a7b0ab;\n      pointer-events: none;\n    }\n\n    .next {\n      min-height: 58px;\n      border-radius: 8px;\n      background: #eef5ff;\n      color: var(--deep);\n      color: white;\n      display: grid;\n      place-items: center;\n    }\n\n    .status-grid {\n      display: grid;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      gap: 8px;\n    }\n\n    .status {\n      min-height: 74px;\n      border-radius: 8px;\n      background: #f7f9fc;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      font-weight: 700;\n    }\n\n    .status[data-kind=\"hot\"] { background: #eef6ff; color: var(--blue); border-color: #d5e7ff; }\n    .status[data-kind=\"later\"] { background: #fff6ed; color: var(--amber); border-color: #ffe3c7; }\n    .status[data-kind=\"bad\"] { background: #fff1f2; color: var(--red); border-color: #ffd4d9; }\n\n    .notes {\n      display: grid;\n      gap: 8px;\n    }\n\n    textarea, input {\n      width: 100%;\n      border-radius: 8px;\n      border: 1px solid var(--line);\n      background: #fff;\n      color: var(--ink);\n      padding: 12px;\n      outline: none;\n    }\n\n    textarea {\n      min-height: 88px;\n      resize: vertical;\n    }\n\n    .section {\n      padding: 0;\n      display: grid;\n      gap: 12px;\n      border: 0;\n      box-shadow: none;\n    }\n\n    .section-title {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n    }\n\n    .section-title h3 {\n      margin: 0;\n      font-size: 16px;\n    }\n\n    .section-title span {\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .tabs {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 6px;\n      background: #f3f6fb;\n      padding: 5px;\n      border-radius: 8px;\n    }\n\n    .tab {\n      min-height: 38px;\n      border-radius: 7px;\n      color: #6f7fa1;\n      background: transparent;\n      font-weight: 700;\n    }\n\n    .tab.active {\n      background: #fff;\n      color: var(--deep);\n      box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n    }\n\n    .tab-panel {\n      display: none;\n      gap: 10px;\n    }\n\n    .tab-panel.active {\n      display: grid;\n    }\n\n    .actions {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 8px;\n    }\n\n    .file-picker {\n      display: grid;\n      gap: 8px;\n      padding: 12px;\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      background: #fbfcfa;\n    }\n\n    .file-picker input {\n      padding: 10px;\n      background: #fff;\n    }\n\n    .secondary {\n      min-height: 46px;\n      border-radius: 8px;\n      background: #fff;\n      border: 1px solid var(--line);\n      color: var(--ink);\n      font-weight: 700;\n    }\n\n    .primary {\n      min-height: 46px;\n      border-radius: 8px;\n      background: var(--deep);\n      color: #fff;\n      font-weight: 800;\n    }\n\n    .danger {\n      color: var(--red);\n    }\n\n    .list {\n      display: grid;\n      gap: 8px;\n      max-height: none;\n      overflow: auto;\n      padding-right: 2px;\n    }\n\n    .row {\n      border: 0;\n      border-bottom: 1px solid var(--line);\n      background: #fff;\n      border-radius: 0;\n      padding: 12px 4px;\n      display: grid;\n      grid-template-columns: 1fr 76px;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .row.current {\n      background: #f7faff;\n    }\n\n    .row button {\n      background: transparent;\n      text-align: left;\n      padding: 0;\n      color: inherit;\n      min-width: 0;\n    }\n\n    .row-call {\n      min-height: 38px;\n      border-radius: 8px;\n      background: #eef5ff;\n      color: var(--blue);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 4px;\n      font-size: 13px;\n      font-weight: 800;\n      text-decoration: none;\n    }\n\n    .row-call svg {\n      width: 16px;\n      height: 16px;\n    }\n\n    .row-call[aria-disabled=\"true\"] {\n      color: #aeb8cc;\n      pointer-events: none;\n    }\n\n    .row-main {\n      display: flex;\n      justify-content: space-between;\n      gap: 8px;\n      font-size: 14px;\n      font-weight: 800;\n    }\n\n    .row-sub {\n      color: var(--muted);\n      font-size: 12px;\n    }\n\n    .empty {\n      border: 1px dashed #b8c1bc;\n      border-radius: 8px;\n      padding: 16px;\n      color: var(--muted);\n      text-align: center;\n      background: #fbfcfa;\n    }\n\n    .export-box {\n      min-height: 180px;\n      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n      font-size: 12px;\n      line-height: 1.45;\n      white-space: pre;\n      overflow: auto;\n    }\n\n    .hint {\n      color: var(--muted);\n      font-size: 12px;\n      line-height: 1.5;\n    }\n\n    .toast {\n      position: fixed;\n      left: 14px;\n      right: 14px;\n      bottom: calc(14px + env(safe-area-inset-bottom));\n      min-height: 46px;\n      border-radius: 8px;\n      background: rgba(7, 38, 91, .96);\n      color: white;\n      display: none;\n      place-items: center;\n      padding: 12px;\n      z-index: 20;\n      text-align: center;\n      box-shadow: var(--shadow);\n    }\n\n    .toast.show {\n      display: grid;\n    }\n\n    svg {\n      width: 22px;\n      height: 22px;\n      stroke: currentColor;\n      stroke-width: 2.2;\n      stroke-linecap: round;\n      stroke-linejoin: round;\n      fill: none;\n    }\n\n    .back {\n      position: absolute;\n      left: 0;\n      top: 7px;\n      width: 36px;\n      height: 36px;\n      border-radius: 8px;\n      background: transparent;\n      color: var(--deep);\n      display: none;\n      place-items: center;\n    }\n\n    .app.action-mode .back { display: grid; }\n    .app.action-mode .section { display: none; }\n    .app:not(.action-mode) .hero { display: none; }\n\n    .search {\n      position: relative;\n    }\n\n    .search input {\n      padding-left: 38px;\n      height: 42px;\n    }\n\n    .search svg {\n      position: absolute;\n      left: 12px;\n      top: 10px;\n      color: #7a88a6;\n      width: 19px;\n      height: 19px;\n    }\n\n    .target-card {\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      padding: 16px;\n      display: grid;\n      gap: 4px;\n      margin-bottom: 8px;\n    }\n  </style>\n</head>\n<body>\n  <main class=\"app\" id=\"app\">\n    <header>\n      <button class=\"back\" id=\"backToList\" aria-label=\"リストへ戻る\" title=\"リストへ戻る\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"m15 18-6-6 6-6\"/></svg>\n      </button>\n      <div class=\"brand\">\n        <div class=\"mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg>\n        </div>\n        <div>\n          <h1>テレアポ架電サポート</h1>\n          <p>番号準備、発信、結果記録を1画面で</p>\n        </div>\n      </div>\n      <div class=\"pill\" id=\"progressPill\">0 / 0</div>\n    </header>\n\n    <div class=\"grid\">\n      <section class=\"panel hero\" aria-label=\"現在の架電先\">\n        <div class=\"meta\">\n          <span id=\"queueLabel\">架電リストなし</span>\n          <span id=\"lastStatus\">未記録</span>\n        </div>\n\n        <div class=\"target-card\">\n          <div class=\"target\">\n            <h2 id=\"targetName\">CSVを追加してください</h2>\n            <div class=\"company\" id=\"targetCompany\">会社名、担当者名、電話番号を読み込めます</div>\n          </div>\n\n          <div class=\"phone\">\n            <strong id=\"targetPhone\">---</strong>\n            <button class=\"icon-button\" id=\"copyPhone\" aria-label=\"電話番号をコピー\" title=\"電話番号をコピー\">\n              <svg viewBox=\"0 0 24 24\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n            </button>\n          </div>\n        </div>\n\n        <div class=\"call-row\">\n          <a class=\"call\" id=\"callLink\" href=\"#\" aria-disabled=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg>\n            この番号に発信\n          </a>\n          <button class=\"next\" id=\"nextButton\" aria-label=\"次へ\" title=\"次へ\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M5 12h14\"/><path d=\"m12 5 7 7-7 7\"/></svg>\n          </button>\n        </div>\n\n        <div class=\"status-grid\" aria-label=\"通話結果\">\n          <button class=\"status\" data-result=\"不在\">不在</button>\n          <button class=\"status\" data-result=\"担当者不在\">担当者不在</button>\n          <button class=\"status\" data-result=\"再架電\" data-kind=\"later\">再架電</button>\n          <button class=\"status\" data-result=\"見込みあり\" data-kind=\"hot\">見込みあり</button>\n          <button class=\"status\" data-result=\"資料送付\" data-kind=\"hot\">資料送付</button>\n          <button class=\"status\" data-result=\"受付NG\" data-kind=\"bad\">受付NG</button>\n          <button class=\"status\" data-result=\"番号違い\" data-kind=\"bad\">番号違い</button>\n          <button class=\"status\" data-result=\"完了\">完了</button>\n        </div>\n\n        <div class=\"notes\">\n          <input id=\"callbackAt\" type=\"datetime-local\" aria-label=\"再架電日時\">\n          <textarea id=\"memo\" placeholder=\"会話メモ、受付名、次回アクションなど\"></textarea>\n          <button class=\"primary\" id=\"saveMemo\">メモだけ保存</button>\n        </div>\n      </section>\n\n      <section class=\"panel section\" aria-label=\"リスト管理\">\n        <div class=\"tabs\" role=\"tablist\">\n          <button class=\"tab active\" data-tab=\"list\" role=\"tab\">リスト</button>\n          <button class=\"tab\" data-tab=\"import\" role=\"tab\">追加</button>\n          <button class=\"tab\" data-tab=\"export\" role=\"tab\">出力</button>\n        </div>\n\n        <div class=\"tab-panel active\" id=\"tab-list\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>架電先</h3>\n            <span id=\"countLabel\">0件</span>\n          </div>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"openExport\">リストを出力</button>\n            <button class=\"secondary\" id=\"copyListCsv\">リストをコピー</button>\n          </div>\n          <div class=\"search\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.35-4.35\"/></svg>\n            <input id=\"searchInput\" placeholder=\"会社名・担当者名で検索\" autocomplete=\"off\">\n          </div>\n          <div class=\"list\" id=\"contactList\"></div>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-import\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>CSVファイル取り込み</h3>\n            <span>スマホから選択</span>\n          </div>\n          <div class=\"file-picker\">\n            <input id=\"csvFile\" type=\"file\" accept=\".csv,text/csv\" aria-label=\"CSVファイルを選択\">\n            <p class=\"hint\">Androidのファイル、Google Drive、ダウンロード内のCSVを選べます。</p>\n          </div>\n\n          <div class=\"section-title\">\n            <h3>CSV貼り付け</h3>\n            <span>名前,会社,電話</span>\n          </div>\n          <textarea id=\"csvInput\" placeholder=\"例&#10;山田太郎,山田工務店,090-1234-5678&#10;佐藤花子,佐藤商事,03-1234-5678\"></textarea>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"importCsv\">CSVを取り込む</button>\n            <button class=\"secondary\" id=\"loadSample\">サンプル</button>\n          </div>\n\n          <div class=\"section-title\">\n            <h3>1件追加</h3>\n            <span>手入力</span>\n          </div>\n          <input id=\"manualName\" placeholder=\"担当者名\">\n          <input id=\"manualCompany\" placeholder=\"会社名\">\n          <input id=\"manualPhone\" inputmode=\"tel\" placeholder=\"電話番号\">\n          <button class=\"primary\" id=\"addManual\">追加する</button>\n          <p class=\"hint\">CSVの1行目が見出しでも取り込めます。電話番号らしい列を自動で探します。</p>\n        </div>\n\n        <div class=\"tab-panel\" id=\"tab-export\" role=\"tabpanel\">\n          <div class=\"section-title\">\n            <h3>記録の出力</h3>\n            <span>CSV</span>\n          </div>\n          <div class=\"actions\">\n            <button class=\"primary\" id=\"exportCsv\">CSVをダウンロード</button>\n            <button class=\"secondary\" id=\"copyCsv\">CSVをコピー</button>\n          </div>\n          <div class=\"actions\">\n            <button class=\"secondary\" id=\"shareCsv\">共有する</button>\n            <button class=\"secondary\" id=\"refreshExport\">表示を更新</button>\n          </div>\n          <textarea class=\"export-box\" id=\"exportText\" readonly aria-label=\"出力CSV\"></textarea>\n          <button class=\"secondary danger\" id=\"clearData\">全データを削除</button>\n          <p class=\"hint\">データはこの端末のブラウザ内に保存されます。サーバーには送信しません。</p>\n        </div>\n      </section>\n    </div>\n  </main>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script>\n    const STORAGE_KEY = \"teleapo-assist-v1\";\n    const $ = (selector) => document.querySelector(selector);\n    const $$ = (selector) => Array.from(document.querySelectorAll(selector));\n\n    const state = loadState();\n\n    function loadState() {\n      try {\n        const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || \"{}\");\n        return {\n          contacts: Array.isArray(saved.contacts) ? saved.contacts : [],\n          current: Number.isInteger(saved.current) ? saved.current : 0\n        };\n      } catch {\n        return { contacts: [], current: 0 };\n      }\n    }\n\n    function persist() {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n    }\n\n    function normalizePhone(value) {\n      return String(value || \"\").replace(/[^\\d+]/g, \"\");\n    }\n\n    function displayPhone(value) {\n      return String(value || \"\").trim() || \"---\";\n    }\n\n    function currentContact() {\n      if (!state.contacts.length) return null;\n      if (state.current < 0) state.current = 0;\n      if (state.current >= state.contacts.length) state.current = state.contacts.length - 1;\n      return state.contacts[state.current];\n    }\n\n    function render() {\n      const contact = currentContact();\n      const total = state.contacts.length;\n      $(\"#progressPill\").textContent = total ? `${state.current + 1} / ${total}` : \"0 / 0\";\n      $(\"#countLabel\").textContent = `${total}件`;\n      $(\"#queueLabel\").textContent = total ? `次の架電先` : \"架電リストなし\";\n      updateExportPreview();\n\n      if (!contact) {\n        $(\"#targetName\").textContent = \"CSVを追加してください\";\n        $(\"#targetCompany\").textContent = \"会社名、担当者名、電話番号を読み込めます\";\n        $(\"#targetPhone\").textContent = \"---\";\n        $(\"#lastStatus\").textContent = \"未記録\";\n        $(\"#memo\").value = \"\";\n        $(\"#callbackAt\").value = \"\";\n        $(\"#callLink\").href = \"#\";\n        $(\"#callLink\").setAttribute(\"aria-disabled\", \"true\");\n        renderList();\n        return;\n      }\n\n      $(\"#targetName\").textContent = contact.company || contact.name || \"名前なし\";\n      $(\"#targetCompany\").textContent = contact.name || \"担当者なし\";\n      $(\"#targetPhone\").textContent = displayPhone(contact.phone);\n      $(\"#lastStatus\").textContent = contact.result || \"未記録\";\n      $(\"#memo\").value = contact.memo || \"\";\n      $(\"#callbackAt\").value = contact.callbackAt || \"\";\n\n      const normalized = normalizePhone(contact.phone);\n      $(\"#callLink\").href = normalized ? `tel:${normalized}` : \"#\";\n      $(\"#callLink\").setAttribute(\"aria-disabled\", normalized ? \"false\" : \"true\");\n      renderList();\n      persist();\n    }\n\n    function renderList() {\n      const list = $(\"#contactList\");\n      list.innerHTML = \"\";\n      if (!state.contacts.length) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"empty\";\n        empty.textContent = \"追加タブから架電先を入れてください\";\n        list.appendChild(empty);\n        return;\n      }\n\n      const query = ($(\"#searchInput\")?.value || \"\").trim().toLowerCase();\n      const visibleContacts = state.contacts\n        .map((contact, index) => ({ contact, index }))\n        .filter(({ contact }) => {\n          if (!query) return true;\n          return [contact.name, contact.company, contact.phone, contact.result]\n            .join(\" \")\n            .toLowerCase()\n            .includes(query);\n        });\n\n      if (!visibleContacts.length) {\n        const empty = document.createElement(\"div\");\n        empty.className = \"empty\";\n        empty.textContent = \"一致する架電先がありません\";\n        list.appendChild(empty);\n        return;\n      }\n\n      visibleContacts.forEach(({ contact, index }) => {\n        const row = document.createElement(\"div\");\n        row.className = `row${index === state.current ? \" current\" : \"\"}`;\n        const button = document.createElement(\"button\");\n        button.type = \"button\";\n        button.addEventListener(\"click\", () => {\n          state.current = index;\n          render();\n          switchTab(\"action\");\n        });\n        button.innerHTML = `\n          <div class=\"row-main\">\n            <span>${escapeHtml(contact.company || contact.name || \"名前なし\")}</span>\n            <span>${escapeHtml(contact.result || \"\")}</span>\n          </div>\n          <div class=\"row-sub\">${escapeHtml(contact.name || \"担当者なし\")}　${escapeHtml(displayPhone(contact.phone))}</div>\n        `;\n        const call = document.createElement(\"a\");\n        const phone = normalizePhone(contact.phone);\n        call.className = \"row-call\";\n        call.href = phone ? `tel:${phone}` : \"#\";\n        call.setAttribute(\"aria-label\", `${contact.company || contact.name || \"架電先\"}に電話する`);\n        call.setAttribute(\"aria-disabled\", phone ? \"false\" : \"true\");\n        call.innerHTML = `<svg viewBox=\"0 0 24 24\"><path d=\"M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.2 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.33 1.77.62 2.6a2 2 0 0 1-.45 2.11L8 9.71a16 16 0 0 0 6.29 6.29l1.28-1.28a2 2 0 0 1 2.11-.45c.83.29 1.7.5 2.6.62A2 2 0 0 1 22 16.92z\"/></svg><span>発信</span>`;\n        row.appendChild(button);\n        row.appendChild(call);\n        list.appendChild(row);\n      });\n    }\n\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, (char) => ({\n        \"&\": \"&amp;\",\n        \"<\": \"&lt;\",\n        \">\": \"&gt;\",\n        \"\\\"\": \"&quot;\",\n        \"'\": \"&#039;\"\n      }[char]));\n    }\n\n    function parseCsv(text) {\n      const rows = [];\n      let field = \"\";\n      let row = [];\n      let quoted = false;\n\n      for (let i = 0; i < text.length; i += 1) {\n        const char = text[i];\n        const next = text[i + 1];\n        if (char === \"\\\"\" && quoted && next === \"\\\"\") {\n          field += \"\\\"\";\n          i += 1;\n        } else if (char === \"\\\"\") {\n          quoted = !quoted;\n        } else if (char === \",\" && !quoted) {\n          row.push(field.trim());\n          field = \"\";\n        } else if ((char === \"\\n\" || char === \"\\r\") && !quoted) {\n          if (char === \"\\r\" && next === \"\\n\") i += 1;\n          row.push(field.trim());\n          if (row.some(Boolean)) rows.push(row);\n          row = [];\n          field = \"\";\n        } else {\n          field += char;\n        }\n      }\n      row.push(field.trim());\n      if (row.some(Boolean)) rows.push(row);\n      return rows;\n    }\n\n    function rowsToContacts(rows) {\n      if (!rows.length) return [];\n      const header = rows[0].map((cell) => cell.toLowerCase());\n      const hasHeader = header.some((cell) => /name|名前|担当|会社|company|phone|tel|電話/.test(cell));\n      const body = hasHeader ? rows.slice(1) : rows;\n\n      const phoneIndex = hasHeader ? header.findIndex((cell) => /phone|tel|電話|番号/.test(cell)) : -1;\n      const nameIndex = hasHeader ? header.findIndex((cell) => /name|名前|担当/.test(cell)) : -1;\n      const companyIndex = hasHeader ? header.findIndex((cell) => /company|会社|法人|店舗/.test(cell)) : -1;\n\n      return body.map((cells) => {\n        const guessedPhone = phoneIndex >= 0 ? cells[phoneIndex] : cells.find((cell) => /0\\d{1,4}[-\\d\\s()]{6,}/.test(cell)) || cells[2] || \"\";\n        const guessedName = nameIndex >= 0 ? cells[nameIndex] : cells[0] || \"\";\n        const guessedCompany = companyIndex >= 0 ? cells[companyIndex] : cells[1] || \"\";\n        return {\n          id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),\n          name: guessedName,\n          company: guessedCompany,\n          phone: guessedPhone,\n          result: \"\",\n          memo: \"\",\n          callbackAt: \"\",\n          updatedAt: \"\"\n        };\n      }).filter((contact) => contact.phone || contact.name || contact.company);\n    }\n\n    function markResult(result) {\n      const contact = currentContact();\n      if (!contact) return toast(\"先に架電先を追加してください\");\n      contact.result = result;\n      contact.memo = $(\"#memo\").value.trim();\n      contact.callbackAt = $(\"#callbackAt\").value;\n      contact.updatedAt = new Date().toISOString();\n      persist();\n      toast(`${result}で記録しました`);\n      if (state.current < state.contacts.length - 1) {\n        state.current += 1;\n      }\n      render();\n    }\n\n    function toCsv() {\n      const header = [\"名前\", \"会社\", \"電話番号\", \"結果\", \"再架電日時\", \"メモ\", \"更新日時\"];\n      const lines = state.contacts.map((contact) => [\n        contact.name,\n        contact.company,\n        contact.phone,\n        contact.result,\n        contact.callbackAt,\n        contact.memo,\n        contact.updatedAt\n      ].map(csvCell).join(\",\"));\n      return [header.join(\",\"), ...lines].join(\"\\n\");\n    }\n\n    function updateExportPreview() {\n      const box = $(\"#exportText\");\n      if (!box) return;\n      box.value = state.contacts.length ? toCsv() : \"出力できるリストがありません\";\n    }\n\n    function csvCell(value) {\n      const text = String(value || \"\");\n      return /[\",\\n\\r]/.test(text) ? `\"${text.replace(/\"/g, \"\\\"\\\"\")}\"` : text;\n    }\n\n    function toast(message) {\n      const element = $(\"#toast\");\n      element.textContent = message;\n      element.classList.add(\"show\");\n      window.clearTimeout(toast.timer);\n      toast.timer = window.setTimeout(() => element.classList.remove(\"show\"), 1800);\n    }\n\n    function switchTab(name) {\n      $(\"#app\").classList.toggle(\"action-mode\", name === \"action\");\n      if (name === \"action\") return;\n      $$(\".tab\").forEach((item) => item.classList.toggle(\"active\", item.dataset.tab === name));\n      $$(\".tab-panel\").forEach((item) => item.classList.toggle(\"active\", item.id === `tab-${name}`));\n      if (name === \"export\") updateExportPreview();\n    }\n\n    $$(\".tab\").forEach((tab) => {\n      tab.addEventListener(\"click\", () => switchTab(tab.dataset.tab));\n    });\n\n    $$(\".status\").forEach((button) => {\n      button.addEventListener(\"click\", () => markResult(button.dataset.result));\n    });\n\n    $(\"#nextButton\").addEventListener(\"click\", () => {\n      if (!state.contacts.length) return toast(\"架電先がありません\");\n      state.current = Math.min(state.current + 1, state.contacts.length - 1);\n      render();\n    });\n\n    $(\"#backToList\").addEventListener(\"click\", () => {\n      switchTab(\"list\");\n    });\n\n    $(\"#searchInput\").addEventListener(\"input\", () => {\n      renderList();\n    });\n\n    $(\"#copyPhone\").addEventListener(\"click\", async () => {\n      const contact = currentContact();\n      if (!contact || !contact.phone) return toast(\"コピーする番号がありません\");\n      try {\n        await navigator.clipboard.writeText(contact.phone);\n        toast(\"電話番号をコピーしました\");\n      } catch {\n        toast(\"コピーできませんでした\");\n      }\n    });\n\n    $(\"#openExport\").addEventListener(\"click\", () => {\n      switchTab(\"export\");\n      toast(\"出力タブを開きました\");\n    });\n\n    $(\"#copyListCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"コピーするリストがありません\");\n      try {\n        await navigator.clipboard.writeText(toCsv());\n        toast(\"リストをコピーしました\");\n      } catch {\n        switchTab(\"export\");\n        $(\"#exportText\").select();\n        toast(\"出力欄を選択しました\");\n      }\n    });\n\n    $(\"#saveMemo\").addEventListener(\"click\", () => {\n      const contact = currentContact();\n      if (!contact) return toast(\"先に架電先を追加してください\");\n      contact.memo = $(\"#memo\").value.trim();\n      contact.callbackAt = $(\"#callbackAt\").value;\n      contact.updatedAt = new Date().toISOString();\n      persist();\n      render();\n      toast(\"メモを保存しました\");\n    });\n\n    $(\"#importCsv\").addEventListener(\"click\", () => {\n      const contacts = rowsToContacts(parseCsv($(\"#csvInput\").value));\n      if (!contacts.length) return toast(\"取り込める行がありません\");\n      state.contacts.push(...contacts);\n      if (state.contacts.length === contacts.length) state.current = 0;\n      $(\"#csvInput\").value = \"\";\n      persist();\n      render();\n      toast(`${contacts.length}件取り込みました`);\n    });\n\n    $(\"#csvFile\").addEventListener(\"change\", async (event) => {\n      const file = event.target.files && event.target.files[0];\n      if (!file) return;\n\n      try {\n        const text = await file.text();\n        const contacts = rowsToContacts(parseCsv(text));\n        if (!contacts.length) {\n          event.target.value = \"\";\n          return toast(\"取り込める行がありません\");\n        }\n        state.contacts.push(...contacts);\n        if (state.contacts.length === contacts.length) state.current = 0;\n        persist();\n        render();\n        toast(`${contacts.length}件取り込みました`);\n      } catch {\n        toast(\"CSVを読み込めませんでした\");\n      } finally {\n        event.target.value = \"\";\n      }\n    });\n\n    $(\"#loadSample\").addEventListener(\"click\", () => {\n      $(\"#csvInput\").value = \"名前,会社,電話番号\\n山田太郎,山田工務店,090-1234-5678\\n佐藤花子,佐藤商事,03-1234-5678\";\n    });\n\n    $(\"#addManual\").addEventListener(\"click\", () => {\n      const contact = {\n        id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),\n        name: $(\"#manualName\").value.trim(),\n        company: $(\"#manualCompany\").value.trim(),\n        phone: $(\"#manualPhone\").value.trim(),\n        result: \"\",\n        memo: \"\",\n        callbackAt: \"\",\n        updatedAt: \"\"\n      };\n      if (!contact.name && !contact.company && !contact.phone) return toast(\"追加内容を入力してください\");\n      state.contacts.push(contact);\n      state.current = state.contacts.length - 1;\n      $(\"#manualName\").value = \"\";\n      $(\"#manualCompany\").value = \"\";\n      $(\"#manualPhone\").value = \"\";\n      persist();\n      render();\n      toast(\"1件追加しました\");\n    });\n\n    $(\"#exportCsv\").addEventListener(\"click\", () => {\n      if (!state.contacts.length) return toast(\"出力するリストがありません\");\n      const blob = new Blob([toCsv()], { type: \"text/csv;charset=utf-8\" });\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement(\"a\");\n      link.href = url;\n      link.download = `teleapo-${new Date().toISOString().slice(0, 10)}.csv`;\n      link.click();\n      URL.revokeObjectURL(url);\n    });\n\n    $(\"#copyCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"コピーするリストがありません\");\n      try {\n        await navigator.clipboard.writeText(toCsv());\n        toast(\"CSVをコピーしました\");\n      } catch {\n        $(\"#exportText\").select();\n        toast(\"出力欄を選択しました\");\n      }\n    });\n\n    $(\"#shareCsv\").addEventListener(\"click\", async () => {\n      if (!state.contacts.length) return toast(\"共有するリストがありません\");\n      if (!navigator.share) {\n        $(\"#exportText\").select();\n        return toast(\"共有非対応なので出力欄を選択しました\");\n      }\n      try {\n        await navigator.share({\n          title: \"テレアポ架電リスト\",\n          text: toCsv()\n        });\n      } catch {\n        toast(\"共有をキャンセルしました\");\n      }\n    });\n\n    $(\"#refreshExport\").addEventListener(\"click\", () => {\n      updateExportPreview();\n      toast(\"出力表示を更新しました\");\n    });\n\n    $(\"#clearData\").addEventListener(\"click\", () => {\n      if (!confirm(\"すべての架電先と記録を削除しますか？\")) return;\n      state.contacts = [];\n      state.current = 0;\n      persist();\n      render();\n      toast(\"削除しました\");\n    });\n\n    if (\"serviceWorker\" in navigator && location.protocol !== \"file:\") {\n      navigator.serviceWorker.register(\"./sw.js\").catch(() => {});\n    }\n\n    render();\n  </script>\n</body>\n</html>\n",
    "type": "text/html; charset=utf-8"
  },
  "/manifest.webmanifest": {
    "body": "{\n  \"name\": \"テレアポ架電サポート\",\n  \"short_name\": \"テレアポ\",\n  \"description\": \"Androidで営業テレアポを素早く回すための架電サポートツール\",\n  \"start_url\": \"./index.html\",\n  \"display\": \"standalone\",\n  \"background_color\": \"#f7f8f5\",\n  \"theme_color\": \"#122620\",\n  \"icons\": [\n    {\n      \"src\": \"./icon.svg\",\n      \"sizes\": \"192x192\",\n      \"type\": \"image/svg+xml\",\n      \"purpose\": \"any maskable\"\n    }\n  ]\n}\n",
    "type": "application/manifest+json; charset=utf-8"
  },
  "/sw.js": {
    "body": "const CACHE_NAME = \"teleapo-assist-v4\";\nconst ASSETS = [\"./\", \"./index.html\", \"./manifest.webmanifest\", \"./icon.svg\"];\n\nself.addEventListener(\"install\", (event) => {\n  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS)));\n  self.skipWaiting();\n});\n\nself.addEventListener(\"activate\", (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))))\n  );\n  self.clients.claim();\n});\n\nself.addEventListener(\"fetch\", (event) => {\n  if (event.request.method !== \"GET\") return;\n  event.respondWith(caches.match(event.request).then((cached) => cached || fetch(event.request)));\n});\n",
    "type": "text/javascript; charset=utf-8"
  },
  "/icon.svg": {
    "body": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 192 192\">\n  <rect width=\"192\" height=\"192\" rx=\"36\" fill=\"#122620\"/>\n  <path d=\"M137 116v23c0 10-8 18-18 18-47 0-84-37-84-84 0-10 8-18 18-18h23c5 0 9 3 11 8l8 20c2 5 1 10-3 14l-9 9c7 12 17 22 29 29l9-9c4-4 9-5 14-3l20 8c5 2 8 6 8 11Z\" fill=\"#d8f3dc\"/>\n  <path d=\"M119 49h30v30M148 50l-42 42\" stroke=\"#74c69d\" stroke-width=\"14\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n</svg>\n",
    "type": "image/svg+xml; charset=utf-8"
  }
};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname.endsWith("/") && url.pathname !== "/" ? url.pathname.slice(0, -1) : url.pathname;
    const file = FILES[path] || FILES["/index.html"];
    return new Response(file.body, {
      headers: {
        "content-type": file.type,
        "cache-control": path === "/sw.js" ? "no-cache" : "public, max-age=300"
      }
    });
  }
};
